(function(){
// Status is computed against Cambodia local time (Asia/Bangkok, UTC+7), not the visitor's device timezone
var DAY_INDEX={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
function cambodiaNow(){
  var fmt=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Bangkok',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false});
  var parts=fmt.formatToParts(new Date()),map={};
  parts.forEach(function(p){map[p.type]=p.value;});
  var hour=parseInt(map.hour,10)%24;
  return{day:DAY_INDEX[map.weekday],hourFloat:hour+parseInt(map.minute,10)/60};
}
function isOpenNow(ranges,hourFloat){
  return(ranges||[]).some(function(r){return hourFloat>=r[0]&&hourFloat<r[1];});
}
function setStatuses(){
  var now=cambodiaNow();
  document.querySelectorAll('.tab-panel[data-hours]').forEach(function(panel){
    var hours=JSON.parse(panel.getAttribute('data-hours')),ranges=hours[String(now.day)],
        open=isOpenNow(ranges,now.hourFloat),
        dot=panel.querySelector('[data-status]'),txt=panel.querySelector('[data-status-text]');
    if(!dot||!txt)return;
    dot.className='dot '+(open?'is-open':'is-closed');
    txt.textContent=open?'Open now':'Closed now';
  });
}
// Lightweight CTA tracking hook — wire trackEvent to Plausible/Umami later; no-ops to console by default
window.trackEvent=window.trackEvent||function(name,meta){if(window.console&&console.debug)console.debug('[track]',name,meta||{});};
function bindTracking(){
  document.querySelectorAll('[data-track]').forEach(function(el){
    el.addEventListener('click',function(){window.trackEvent(el.getAttribute('data-track'),{href:el.getAttribute('href')});});
  });
}
document.addEventListener('DOMContentLoaded',function(){setStatuses();bindTracking();});
})();
